begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('d1111100-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','route-'||n||'@example.test','',now(),'{"provider":"email","providers":["email"]}','{"display_name":"Proxy fixture"}',now(),now()from generate_series(1,6)n;
create temp table rr(k text primary key,v uuid);
insert into rr select 'u'||n,p.id from generate_series(1,6)n join public.participants p on p.auth_user_id=('d1111100-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
grant all on rr to authenticated;
create function pg_temp.rid(k text)returns uuid language sql as $$select v from rr where rr.k=$1$$;
create function pg_temp.rclaim(n int)returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','d1111100-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','is_anonymous',false)::text,true);end$$;
create function pg_temp.rpayment(k text,p int,r int,amount bigint,via int default null,route bigint default null,c text default 'VND')returns jsonb language sql as $$select jsonb_build_object('id',k,'payer',pg_temp.rid('u'||p),'recipient',pg_temp.rid('u'||r),'tenderCurrency',c,'tenderMinor',amount,'method',case when c='MYR'then'bank_transfer'else'cash'end)||case when via is null then'{}'::jsonb else jsonb_build_object('via',jsonb_build_object('person',pg_temp.rid('u'||via),'minor',route))end$$;
create function pg_temp.rdraft(rows jsonb)returns jsonb language sql as $$select jsonb_build_object('rateMode','custom','vndPerMyr','6000','payments',rows)$$;
create function pg_temp.rbill(trip uuid,creditor int,debtor int,n bigint,c text default 'VND')returns uuid language plpgsql as $$declare e jsonb;begin e:=public.create_trip_expense_editor(gen_random_uuid(),trip,jsonb_build_object('expense_scope','space','target_space_id',trip,'participant_ids',array[pg_temp.rid('u'||creditor),pg_temp.rid('u'||debtor)],'contribution_amounts',array[n,0],'share_amounts',array[0,n],'total_minor',n,'currency_code',c,'description','Proxy fixture','category','Food','occurred_on','2026-11-10'),array[pg_temp.rid('u'||creditor),pg_temp.rid('u'||debtor)]);return(e->>'expense_id')::uuid;end$$;
set local role authenticated;
select pg_temp.rclaim(2);
insert into rr values('trip',public.create_space('trip','Routed isolated',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role)select pg_temp.rid('trip'),pg_temp.rid('u'||n),'view'from unnest(array[1,3,4,5])n;
set local role authenticated;
select pg_temp.rclaim(2);
select pg_temp.rbill(pg_temp.rid('trip'),2,1,280000),pg_temp.rbill(pg_temp.rid('trip'),2,5,100000),pg_temp.rbill(pg_temp.rid('trip'),3,2,400000),pg_temp.rbill(pg_temp.rid('trip'),4,2,100000),pg_temp.rbill(pg_temp.rid('trip'),3,1,250000),pg_temp.rbill(pg_temp.rid('trip'),4,1,20000),pg_temp.rbill(pg_temp.rid('trip'),3,5,260000);
select pg_temp.rclaim(1);
insert into rr values('ps-account',(public.create_personal_account(gen_random_uuid(),'PS VND','cash','VND',null,null,false)->>'account_id')::uuid);
select pg_temp.rclaim(3);
insert into rr values('dav-account',(public.create_personal_account(gen_random_uuid(),'Dav VND','cash','VND',null,null,false)->>'account_id')::uuid);
select pg_temp.rclaim(4);
insert into rr values('alex-account',(public.create_personal_account(gen_random_uuid(),'Alex VND','cash','VND',null,null,false)->>'account_id')::uuid);
select pg_temp.rclaim(5);
insert into rr values('exson-account',(public.create_personal_account(gen_random_uuid(),'Exson VND','cash','VND',null,null,false)->>'account_id')::uuid);
select pg_temp.rclaim(1);
create temp table rv(k text primary key,v jsonb);

-- Actual ownership, not the role label, authorizes the proxy path.
select pg_temp.rclaim(2);
select is(public.get_trip_creator_context(pg_temp.rid('trip'))->>'canRecord','true','real Trip creator can record for other members');
select is(public.get_trip_creator_context(pg_temp.rid('trip'))->>'isCreator','true','actual ownership returned by server');
select pg_temp.rclaim(3);
select is(public.get_trip_creator_context(pg_temp.rid('trip'))->>'canRecord','false','ordinary full member is not an automatic proxy');
select pg_temp.rclaim(2);
insert into rv values('draft',pg_temp.rdraft(jsonb_build_array(pg_temp.rpayment('dav',1,3,400000,2,200000),pg_temp.rpayment('alex',1,4,100000,2,80000)))||jsonb_build_object('occurredAt',to_char(now()at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'note','Actual cash'));
insert into rv values('preview',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='draft')));
select is(jsonb_array_length((select v->'plan'->'issues'from rv where k='preview')),0,'creator review uses full shared route capacities');
insert into rr values('request',gen_random_uuid());
select throws_ok($$select public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='draft'),pg_temp.rid('request'),(select v->>'digest'from rv where k='preview'),(select(v->>'expiresAt')::timestamptz from rv where k='preview'),false)$$,'P0001','creator_attestation_required','explicit actual-payment attestation required');
insert into rv values('record',public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='draft'),pg_temp.rid('request'),(select v->>'digest'from rv where k='preview'),(select(v->>'expiresAt')::timestamptz from rv where k='preview'),true));
insert into rr values('record',(select(v->>'id')::uuid from rv where k='record'));
select is((select v->>'status'from rv where k='record'),'posted','creator directly posts, with no member approvals');
select is((public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='draft'),pg_temp.rid('request'),(select v->>'digest'from rv where k='preview'),(select(v->>'expiresAt')::timestamptz from rv where k='preview'),true)->>'id')::uuid,pg_temp.rid('record'),'committed retry returns original record');
select throws_ok($$select public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v||'{"note":"Changed"}'from rv where k='draft'),pg_temp.rid('request'),(select v->>'digest'from rv where k='preview'),(select(v->>'expiresAt')::timestamptz from rv where k='preview'),true)$$,'P0001','idempotency_conflict','edited retry conflicts');
reset role;
select is((select count(*)::int from private.trip_routed_approvals a join private.trip_routed_proposals p on p.id=a.proposal where p.space_id=pg_temp.rid('trip')),0,'proxy does not fake ordinary routed approvals');
select is((select count(*)::int from private.creator_receipts where record_id=pg_temp.rid('record')and kind='cash'),2,'two actual cash receipts');
select is((select count(*)::int from public.personal_settlement_cash_legs l join private.creator_receipts r on r.payment_id=l.settlement_payment_id where r.record_id=pg_temp.rid('record')),0,'no one else private account is automatically linked');
select is((select count(*)::int from private.creator_outbox where record_id=pg_temp.rid('record')),3,'one outbox event per affected real account, excluding recorder');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u1'),pg_temp.rid('u2'),'VND'),0::bigint,'shared upstream source consumed once');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u2'),pg_temp.rid('u4'),'VND'),20000::bigint,'unpaid recipient balance remains outstanding');
set local role authenticated;
select pg_temp.rclaim(3);
select is(jsonb_array_length(public.read_trip_creator_settlements(pg_temp.rid('trip'))->0->'plan'->'lines'),1,'Dav sees only own related cash line');
select ok(not(public.read_trip_creator_settlements(pg_temp.rid('trip'))->0->'plan' ?|array['sources','native','actors','accounts']),'member response excludes private source and approval internals');
select is(jsonb_array_length(public.get_creator_settlement_notifications()->'notices'),1,'outbox delivered through real application feed');
select is(jsonb_array_length(public.get_creator_settlement_notifications()->'notices'),1,'delivery retry has no duplicate notice');
select pg_temp.rclaim(5);
select is(jsonb_array_length(public.read_trip_creator_settlements(pg_temp.rid('trip'))),0,'uninvolved member cannot view proxy record');
select is(jsonb_array_length(public.get_creator_settlement_notifications()->'notices'),0,'uninvolved member has no notice');

-- Owner-only late linkage and metadata-only correction.
select pg_temp.rclaim(3);
select throws_ok($$select public.link_trip_creator_account(pg_temp.rid('record'),'dav',pg_temp.rid('ps-account'),gen_random_uuid(),1)$$,'P0001','settlement_cash_account_invalid','recipient cannot bind another member account');
insert into rv values('linked',public.link_trip_creator_account(pg_temp.rid('record'),'dav',pg_temp.rid('dav-account'),gen_random_uuid(),1));
select is((select v->>'version'from rv where k='linked'),'2','only own late account link updates version');
select is((public.link_trip_creator_account(pg_temp.rid('record'),'dav',pg_temp.rid('dav-account'),gen_random_uuid(),2)->>'version'),'2','new nonce for same linked side has no extra event or version');
insert into rr values('correction-request',gen_random_uuid());
insert into rv values('correction',public.request_trip_creator_correction(pg_temp.rid('record'),pg_temp.rid('correction-request'),'Wrong actual cash'));
select is((select v->'corrections'->0->>'status'from rv where k='correction'),'pending','involved recipient requests a correction');
select lives_ok($$select public.request_trip_creator_correction(pg_temp.rid('record'),gen_random_uuid(),'Wrong actual cash')$$,'same pending correction with different nonce is deduplicated');
select throws_ok($$select public.request_trip_creator_correction(pg_temp.rid('record'),gen_random_uuid(),'Changed reason')$$,'P0001','creator_correction_pending','pending correction cannot be duplicated with changed text');
reset role;
select is((select count(*)::int from private.creator_corrections where record_id=pg_temp.rid('record')),1,'one pending correction');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('dav-account')),400000::bigint,'late receiver linkage posts actual received VND once');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u1'),pg_temp.rid('u2'),'VND'),0::bigint,'correction request never alters shared balances');
set local role authenticated;
select pg_temp.rclaim(1);
insert into rv values('payer-link',public.link_trip_creator_account(pg_temp.rid('record'),'dav',pg_temp.rid('ps-account'),gen_random_uuid(),3));
select pg_temp.rclaim(5);
select throws_ok($$select public.request_trip_creator_correction(pg_temp.rid('record'),gen_random_uuid(),'Unrelated')$$,'P0001','creator_record_unavailable','uninvolved member cannot request correction');
select pg_temp.rclaim(2);
insert into rr values('reverse-request',gen_random_uuid());
insert into rv values('reversed',public.reverse_trip_creator_settlement(pg_temp.rid('record'),pg_temp.rid('reverse-request'),4,'Wrong cash'));
select is((select v->>'status'from rv where k='reversed'),'reversed','creator can reverse the whole frozen record');
select is(jsonb_array_length((select v->'plan'->'remaining'from rv where k='reversed')),0,'reversed view does not present obsolete remaining balances');
select lives_ok($$select public.reverse_trip_creator_settlement(pg_temp.rid('record'),pg_temp.rid('reverse-request'),4,'Wrong cash')$$,'same reversal nonce returns original result');
reset role;
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('dav-account')),0::bigint,'whole reversal restores late recipient account');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('ps-account')),0::bigint,'whole reversal restores late payer account');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u1'),pg_temp.rid('u2'),'VND'),280000::bigint,'whole reversal restores original upstream VND');
set local role authenticated;
select pg_temp.rclaim(2);
insert into rv values('replace-draft',(select v||jsonb_build_object('replacementFor',pg_temp.rid('record'))from rv where k='draft'));
insert into rv values('replace-review',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='replace-draft')));
insert into rv values('replacement',public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='replace-draft'),gen_random_uuid(),(select v->>'digest'from rv where k='replace-review'),(select(v->>'expiresAt')::timestamptz from rv where k='replace-review'),true));
select is((select v->>'replacementFor'from rv where k='replacement'),pg_temp.rid('record')::text,'new actual recording is traceably linked to reversed original');
select lives_ok($$select public.resolve_trip_creator_correction((select(v->'corrections'->0->>'id')::uuid from rv where k='correction'),gen_random_uuid(),1,'Reversed and re-recorded',(select(v->>'id')::uuid from rv where k='replacement'))$$,'manager resolves correction with linked replacement');
-- Fresh monetary reviews bind membership, current grants and last preview.
insert into rv values('small',pg_temp.rdraft(jsonb_build_array(pg_temp.rpayment('small',5,3,10000)))||jsonb_build_object('occurredAt',now(),'note',''));
select throws_ok($$select public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v||'{"isAdmin":true}'from rv where k='small'))$$,'P0001','creator_invalid_draft','client admin flag is rejected');
select throws_ok($$select public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v||jsonb_build_object('occurredAt',now()+interval'1 day')from rv where k='small'))$$,'P0001','creator_future_payment','future plan cannot be attested as paid');
insert into rv values('grant',public.set_trip_creator_delegate(pg_temp.rid('trip'),pg_temp.rid('u3'),true,gen_random_uuid(),public.get_trip_creator_context(pg_temp.rid('trip'))->>'policyVersion'));
select pg_temp.rclaim(3);
select is(public.get_trip_creator_context(pg_temp.rid('trip'))->>'canRecord','true','explicit current delegate can record others cash');
select throws_ok($$select public.set_trip_creator_delegate(pg_temp.rid('trip'),pg_temp.rid('u5'),true,gen_random_uuid(),public.get_trip_creator_context(pg_temp.rid('trip'))->>'policyVersion')$$,'P0001','creator_proxy_forbidden','delegate cannot delegate onward');
insert into rv values('delegate-review',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='small')));
select pg_temp.rclaim(2);
select public.set_trip_creator_delegate(pg_temp.rid('trip'),pg_temp.rid('u3'),false,gen_random_uuid(),public.get_trip_creator_context(pg_temp.rid('trip'))->>'policyVersion');
select pg_temp.rclaim(3);
select throws_ok($$select public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='small'),gen_random_uuid(),(select v->>'digest'from rv where k='delegate-review'),(select(v->>'expiresAt')::timestamptz from rv where k='delegate-review'),true)$$,'P0001','creator_proxy_forbidden','revoked delegate cannot submit a reviewed record');
select pg_temp.rclaim(2);
insert into rv values('old-review',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='small')));
insert into rv values('latest-review',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v||'{"note":"Latest"}'from rv where k='small')));
select throws_ok($$select public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='small'),gen_random_uuid(),(select v->>'digest'from rv where k='old-review'),(select(v->>'expiresAt')::timestamptz from rv where k='old-review'),true)$$,'P0001','quote_changed','new preview invalidates previous digest');
reset role;
select ok(not has_function_privilege('authenticated','private.routed_build_core(uuid,uuid,jsonb,boolean)','EXECUTE'),'browser cannot invoke privileged core');
select ok(not has_table_privilege('authenticated','private.creator_records','SELECT,INSERT,UPDATE,DELETE'),'no direct record table access');
select ok(not has_function_privilege('anon','public.record_trip_creator_settlement(uuid,jsonb,uuid,text,timestamptz,boolean)','EXECUTE'),'anonymous role cannot post');
-- Every posting stage is in the same transaction as the original ledger.
reset role;
create function pg_temp.proxy_fail()returns trigger language plpgsql as $$begin raise exception using message='proxy_atomic_probe',errcode='P0001';end$$;
create trigger proxy_fail_outbox before insert on private.creator_outbox for each row execute function pg_temp.proxy_fail();
create temp table proxy_counts as select(select count(*)from public.settlement_payments)cash,(select count(*)from private.creator_records)records,(select count(*)from public.financial_events)events,(select count(*)from private.creator_outbox)outbox;
set local role authenticated;
select pg_temp.rclaim(2);
select throws_ok($$select public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v||'{"note":"Latest"}'from rv where k='small'),gen_random_uuid(),(select v->>'digest'from rv where k='latest-review'),(select(v->>'expiresAt')::timestamptz from rv where k='latest-review'),true)$$,'P0001','proxy_atomic_probe','outbox failure rolls back cash, native coverage, audit and history');
reset role;
select is((select count(*)from public.settlement_payments),(select cash from proxy_counts),'failed outbox leaves no payment rows');
select is((select count(*)from private.creator_records),(select records from proxy_counts),'failed outbox leaves no partial creator record');
select is((select count(*)from public.financial_events),(select events from proxy_counts),'failed outbox leaves no financial events');
select is((select count(*)from private.creator_outbox),(select outbox from proxy_counts),'failed outbox leaves no notification half-write');
drop trigger proxy_fail_outbox on private.creator_outbox;
-- Delivery errors retain a retryable outbox item after financial commit.
create trigger proxy_notice_fail before insert on public.creator_settlement_notices for each row execute function pg_temp.proxy_fail();
select private.deliver_creator_notices(null,500);
select ok(exists(select 1 from private.creator_outbox where status='pending'and attempts>0 and last_error='P0001'),'delivery error keeps pending retry with sanitized error code');
drop trigger proxy_notice_fail on public.creator_settlement_notices;
select private.deliver_creator_notices(null,500);
select is((select count(*)::int from private.creator_outbox where status='pending'),0,'retry worker delivers committed notices');
select is((select count(*)from public.creator_settlement_notices),(select count(distinct event_key)from public.creator_settlement_notices),'workers never duplicate an event');
set local role authenticated;
select pg_temp.rclaim(3);
select ok(not exists(select 1 from public.creator_settlement_notices where recipient_id<>pg_temp.rid('u3')),'RLS binds notices to actual viewer');
select pg_temp.rclaim(2);
select public.set_trip_creator_delegate(pg_temp.rid('trip'),pg_temp.rid('u3'),true,gen_random_uuid(),public.get_trip_creator_context(pg_temp.rid('trip'))->>'policyVersion');
select pg_temp.rclaim(3);
insert into rv values('remove-review',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='small')));
reset role;
update public.space_members set removed_at=now()where space_id=pg_temp.rid('trip')and participant_id=pg_temp.rid('u3');
set local role authenticated;
select throws_ok($$select public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='small'),gen_random_uuid(),(select v->>'digest'from rv where k='remove-review'),(select(v->>'expiresAt')::timestamptz from rv where k='remove-review'),true)$$,'P0001','creator_proxy_forbidden','removed delegate cannot post');
select is(jsonb_array_length(public.get_creator_settlement_notifications()->'notices'),0,'removed recipient cannot read previously delivered notices');
reset role;
update public.space_members set role='view'where space_id=pg_temp.rid('trip')and participant_id=pg_temp.rid('u2');
update public.space_members set removed_at=null,role='owner'where space_id=pg_temp.rid('trip')and participant_id=pg_temp.rid('u3');
set local role authenticated;
select is(public.get_trip_creator_context(pg_temp.rid('trip'))->>'canRecord','false','rejoining and owner role label do not restore revoked delegate');
select pg_temp.rclaim(2);
select public.set_trip_creator_delegate(pg_temp.rid('trip'),pg_temp.rid('u3'),true,gen_random_uuid(),public.get_trip_creator_context(pg_temp.rid('trip'))->>'policyVersion');
select pg_temp.rclaim(3);
insert into rv values('transfer-review',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='small')));
reset role;
update public.spaces set owner_participant_id=pg_temp.rid('u5')where id=pg_temp.rid('trip');
set local role authenticated;
select throws_ok($$select public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='small'),gen_random_uuid(),(select v->>'digest'from rv where k='transfer-review'),(select(v->>'expiresAt')::timestamptz from rv where k='transfer-review'),true)$$,'P0001','creator_proxy_forbidden','creator transfer invalidates prior grants');
select pg_temp.rclaim(2);
select is(public.get_trip_creator_context(pg_temp.rid('trip'))->>'canRecord','false','old actual creator no longer has default authorization');
select pg_temp.rclaim(5);
select is(public.get_trip_creator_context(pg_temp.rid('trip'))->>'isCreator','true','new actual owner receives creator authority');

-- Native MYR and VND remain independent; only actual holder links the payer account.
reset role;
update public.space_members set role='view'where space_id=pg_temp.rid('trip')and participant_id=pg_temp.rid('u3');
update public.space_members set role='owner'where space_id=pg_temp.rid('trip')and participant_id=pg_temp.rid('u5');
set local role authenticated;
select pg_temp.rclaim(5);
select pg_temp.rbill(pg_temp.rid('trip'),3,5,600,'MYR');
insert into rr values('exson-myr',(public.create_personal_account(gen_random_uuid(),'Exson MYR','bank','MYR',null,null,false)->>'account_id')::uuid);
insert into rv values('mixed',pg_temp.rdraft(jsonb_build_array(pg_temp.rpayment('cash-vnd',5,3,260000),pg_temp.rpayment('bank-myr',5,3,600,null,null,'MYR')))||jsonb_build_object('occurredAt',now(),'note','Mixed actual','ownAccountLinks',jsonb_build_array(jsonb_build_object('paymentId','cash-vnd','accountId',pg_temp.rid('exson-account')),jsonb_build_object('paymentId','bank-myr','accountId',pg_temp.rid('exson-myr')))));
insert into rv values('mixed-review',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='mixed')));
select is(jsonb_array_length((select v->'plan'->'issues'from rv where k='mixed-review')),0,'mixed actual VND and MYR has exact native coverage');
insert into rv values('mixed-record',public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='mixed'),gen_random_uuid(),(select v->>'digest'from rv where k='mixed-review'),(select(v->>'expiresAt')::timestamptz from rv where k='mixed-review'),true));
reset role;
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('exson-account')),-260000::bigint,'actual VND cash posts in VND');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('exson-myr')),-600::bigint,'actual MYR transfer posts in cents');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u5'),pg_temp.rid('u3'),'VND'),0::bigint,'native VND covered exactly');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u5'),pg_temp.rid('u3'),'MYR'),0::bigint,'native MYR covered exactly');
set local role authenticated;
select public.reverse_trip_creator_settlement((select(v->>'id')::uuid from rv where k='mixed-record'),gen_random_uuid(),1,'Mixed correction');
reset role;
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('exson-account')),0::bigint,'mixed reverse restores original VND cash');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.rid('exson-myr')),0::bigint,'mixed reverse restores original MYR cents');
set local role authenticated;
select pg_temp.rclaim(5);
insert into rr values('u7',public.add_manual_space_member(pg_temp.rid('trip'),'Manual person'));
select pg_temp.rbill(pg_temp.rid('trip'),3,7,12000);
insert into rv values('manual',pg_temp.rdraft(jsonb_build_array(pg_temp.rpayment('manual',7,3,12000)))||jsonb_build_object('occurredAt',now(),'note','Manual actual'));
insert into rv values('manual-review',public.preview_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='manual')));
select is(jsonb_array_length((select v->'plan'->'issues'from rv where k='manual-review')),0,'manual immutable principal can participate in proxy plan');
insert into rv values('manual-record',public.record_trip_creator_settlement(pg_temp.rid('trip'),(select v from rv where k='manual'),gen_random_uuid(),(select v->>'digest'from rv where k='manual-review'),(select(v->>'expiresAt')::timestamptz from rv where k='manual-review'),true));
reset role;
select is((select count(*)::int from private.creator_outbox where record_id=(select(v->>'id')::uuid from rv where k='manual-record')),1,'manual member has no invented auth notice; actual recipient notified once');
select is(private.space_signed_outstanding(pg_temp.rid('trip'),pg_temp.rid('u7'),pg_temp.rid('u3'),'VND'),0::bigint,'manual native debt is authoritatively reduced');

select * from finish();
rollback;
